INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 1, 'What is the time complexity of binary search on a sorted array?', '["O(n)","O(log n)","O(n log n)","O(1)"]'::jsonb, 1, 'Binary search halves the search space each iteration, giving O(log n).', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 1, 'Which sorting algorithm is stable and O(n log n) worst-case?', '["Quick Sort","Heap Sort","Merge Sort","Selection Sort"]'::jsonb, 2, 'Merge sort preserves order of equal elements with guaranteed O(n log n).', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 1, 'Two-pointer technique is commonly used on what?', '["Unsorted arrays only","Sorted arrays and strings","Graphs only","Hash tables only"]'::jsonb, 1, 'Two pointers efficiently solve problems like pair sum on sorted data.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 1, 'What is amortized O(1) for dynamic array append using doubling?', '["True over n appends","False always O(n)","Only linked lists","Only stacks"]'::jsonb, 0, 'Doubling strategy yields O(1) amortized cost per append.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 1, 'Kadane algorithm solves which problem?', '["Maximum subarray sum","Longest path in tree","Graph coloring","Sorting strings"]'::jsonb, 0, 'Kadane computes maximum contiguous subarray sum in O(n).', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 1, 'Rolling hash is used in what type of problems?', '["String pattern matching / substring search","Sorting numbers","BFS","Heapify"]'::jsonb, 0, 'Polynomial rolling hashes compare substrings efficiently in competitive programming.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 1, 'Which structure supports O(1) random access by index?', '["Singly linked list","Array","Stack","Queue"]'::jsonb, 1, 'Arrays provide constant-time indexed access.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 1, 'Sliding window reduces complexity often from O(n^2) to?', '["O(n)","O(log n)","O(n^3)","O(1) always"]'::jsonb, 0, 'Maintaining window state while moving endpoints yields linear time.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 1, 'An anagram check after sorting characters runs in?', '["O(n log n) due to sort","O(1)","O(n^2) only","O(log n)"]'::jsonb, 0, 'Sorting n characters dominates at O(n log n).', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 1, 'Which problem finds longest substring without repeating characters?', '["Sliding window with hash set","DFS only","Dijkstra","Union find only"]'::jsonb, 0, 'Expand/shrink window tracking last seen index solves in O(n).', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 2, 'Insert at head of singly linked list complexity?', '["O(1)","O(n)","O(log n)","O(n log n)"]'::jsonb, 0, 'Head insert updates pointers without traversal.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 2, 'Detect cycle in linked list uses which algorithm?', '["Floyd tortoise-hare","Merge sort","KMP","Prim"]'::jsonb, 0, 'Two pointers at different speeds meet if cycle exists.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 2, 'Reverse linked list iteratively needs how many pointers?', '["Three (prev, curr, next)","One","None","Ten"]'::jsonb, 0, 'Track previous and next while reversing links.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 2, 'Merge two sorted linked lists complexity?', '["O(n+m)","O(n*m)","O(log n)","O(1)"]'::jsonb, 0, 'Single pass merging like merge sort merge step.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 2, 'Why use dummy sentinel node in list problems?', '["Simplify edge cases at head","Increase memory only for fun","Required by language","Slow down always"]'::jsonb, 0, 'Dummy node avoids special-casing empty list or head insert/delete.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 2, 'Find middle of linked list in one pass using?', '["Fast/slow pointers","Sorting list","Stack only","Hash map of values only"]'::jsonb, 0, 'Fast pointer moves 2 steps, slow 1 step; slow at middle when fast ends.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 2, 'Doubly linked list advantage over singly?', '["O(1) deletion given node reference","Less memory","No pointers","Cannot traverse backward"]'::jsonb, 0, 'Previous pointer enables backward traversal and easier deletion.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 2, 'LRU cache often implemented with?', '["Hash map + doubly linked list","Array only","Stack only","BST only"]'::jsonb, 0, 'Map gives O(1) lookup; DLL orders usage for eviction.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 2, 'Space complexity of recursive reverse of n nodes?', '["O(n) stack","O(1)","O(log n)","O(n^2)"]'::jsonb, 0, 'Recursion depth equals list length in worst case.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 2, 'Josephus problem on circular linked list tests understanding of?', '["Pointer manipulation on circular structure","Sorting","Graph BFS","Heap property"]'::jsonb, 0, 'Elimination around circle requires careful next pointer updates.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 3, 'In-order traversal of BST yields?', '["Sorted sequence","Reverse sorted always","Level order","Random order"]'::jsonb, 0, 'Left-root-right visits nodes in ascending key order.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 3, 'Height of balanced BST with n nodes is?', '["O(log n)","O(n)","O(1)","O(n log n)"]'::jsonb, 0, 'Balance keeps tree height logarithmic.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 3, 'Which traversal uses queue?', '["BFS level-order","In-order","Pre-order recursive","Post-order without queue always"]'::jsonb, 0, 'Level-order processes nodes breadth-first using FIFO queue.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 3, 'AVL tree balance factor allowed values?', '["-1, 0, 1","-2, 2 only","Any integer","0 only"]'::jsonb, 0, 'AVL requires balance factor within one for every node.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 3, 'Lowest common ancestor in BST solved by?', '["Exploiting ordering property","Sorting array","Hash only","Dijkstra"]'::jsonb, 0, 'Compare node values with p and q to move left or right.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 3, 'Complete binary tree property means?', '["All levels filled except possibly last left-filled","Every node two children","BST property","Heap only"]'::jsonb, 0, 'Complete trees fill levels left to right without gaps except last level.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 3, 'Segment tree supports range queries in?', '["O(log n) per query/update","O(n) only","O(1) always","O(n^2)"]'::jsonb, 0, 'Tree height O(log n) enables efficient range aggregate queries.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 3, 'Trie complexity of search for word length L?', '["O(L)","O(n)","O(log n)","O(1)"]'::jsonb, 0, 'Search follows one pointer per character.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 3, 'Red-black tree guarantees what about height?', '["At most 2 log(n+1)","Exactly log n","Linear height","Constant height"]'::jsonb, 0, 'RB trees remain approximately balanced with logarithmic height bound.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 3, 'Serialize BST pre-order needs what delimiter handling?', '["Null markers for missing children","Only root value","In-order only","No recursion"]'::jsonb, 0, 'Include sentinel for null children to reconstruct unique shape.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 4, 'Adjacency list space for sparse graph?', '["O(V + E)","O(V^2)","O(E^2)","O(1)"]'::jsonb, 0, 'Lists store each edge once totaling V + E space.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 4, 'Dijkstra fails with negative edges because?', '["Greedy choice invalid","Uses too much memory","Requires BFS only","Only works on trees"]'::jsonb, 0, 'Non-negative weights ensure settled distances are final.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 4, 'Topological sort exists only for?', '["DAG","Any graph with cycle","Undirected connected only","Complete graph only"]'::jsonb, 0, 'Directed acyclic graphs admit linear topological ordering.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 4, 'BFS finds shortest path in unweighted graph because?', '["Explores layer by layer","Uses stack","Sorts edges","Random walk"]'::jsonb, 0, 'First time reaching node is via minimum edge count path.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 4, 'Kruskal algorithm sorts what?', '["Edges by weight","Vertices by degree only","Adjacency matrix rows","Colors"]'::jsonb, 0, 'Kruskal processes edges ascending weight using union-find.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 4, 'Detect cycle in undirected graph using union-find when?', '["Edge connects already connected components","Graph disconnected","All vertices degree 1","Using BFS only always"]'::jsonb, 0, 'Adding edge within same component creates cycle.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 4, 'Bellman-Ford handles negative edges and detects?', '["Negative cycles","Only positive cycles","MST","Euler path only"]'::jsonb, 0, 'Relax all edges V-1 times; Vth pass detects negative cycles.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 4, 'Graph coloring minimum colors problem is?', '["NP-hard in general","O(n) always","Same as BFS","Solvable by sorting"]'::jsonb, 0, 'Finding chromatic number is computationally hard.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 4, 'Strongly connected components in directed graph via?', '["Kosaraju/Tarjan","Prim","KMP","Heap sort"]'::jsonb, 0, 'These algorithms partition vertices into SCCs in linear time.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 4, 'Maximum flow problem solved by?', '["Ford-Fulkerson variants","Binary search on tree","Trie insert","Selection sort"]'::jsonb, 0, 'Augmenting path methods compute max flow in network.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 5, 'DP requires optimal substructure and?', '["Overlapping subproblems","No recursion","Sorted input only","Greedy always sufficient"]'::jsonb, 0, 'Repeated subproblems make memoization/tabulation beneficial.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 5, '0/1 knapsack time with n items capacity W?', '["O(nW) pseudo-polynomial","O(n log W) always","O(1)","O(n^2 W) always required"]'::jsonb, 0, 'Classic DP table fills n by W entries.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 5, 'Longest common subsequence recurrence compares?', '["Match skip or take diagonal","Only sorting strings","Graph edges","Heap root"]'::jsonb, 0, 'If chars match add 1 + LCS(i-1,j-1); else max of excluding one char.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 5, 'Coin change minimum coins DP initializes?', '["Infinity for impossible states except 0 coins for amount 0","All zero","Random values","Only largest coin"]'::jsonb, 0, 'DP builds min coins bottom-up from base amount 0.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 5, 'Fibonacci DP reduces time from exponential to?', '["O(n)","O(2^n)","O(n^2) only always","O(log log n)"]'::jsonb, 0, 'Memoization or tabulation computes each subproblem once.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 5, 'Edit distance (Levenshtein) allowed operations?', '["Insert delete replace","Only swap adjacent","Only delete","Only insert"]'::jsonb, 0, 'Three operations transform one string to another with minimum cost.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 5, 'Matrix chain multiplication DP state?', '["Split k between i and j","Only diagonal","Sort matrices","Greedy largest first always optimal"]'::jsonb, 0, 'Choose partition minimizing scalar multiplication cost.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 5, 'DP on trees often uses?', '["Post-order DFS returning values to parent","BFS only","Hash collisions","No recursion allowed"]'::jsonb, 0, 'Compute answers for subtrees before combining at parent.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 5, 'Subset sum decision problem DP table dimension?', '["Items x target sum","Only items","Only sum","Graph vertices"]'::jsonb, 0, 'Boolean table whether sum achievable using first i items.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (1, 5, 'Space optimize 0/1 knapsack to O(W) using?', '["1D rolling array","Two matrices always","Stack only","Trie"]'::jsonb, 0, 'Iterate capacity backwards updating single row per item.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 6, 'Which is NOT a process state?', '["Ready","Running","Compiled","Waiting"]'::jsonb, 2, 'Compiled is not an OS process scheduling state.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 6, 'fork() on Unix creates?', '["New thread only","Child process copy","New file","Kernel module"]'::jsonb, 1, 'fork duplicates calling process; exec often loads new program.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 6, 'Context switch saves?', '["Process/thread CPU state and switches address space info","Only file names","Only user password","Disk contents always full copy"]'::jsonb, 0, 'Kernel stores registers and memory management context.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 6, 'Zombie process is?', '["Terminated child awaiting wait()","Running virus","Idle CPU thread","Kernel panic"]'::jsonb, 0, 'Entry remains until parent reaps exit status.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 6, 'Thread shares with peers in process?', '["Address space and open files","Stack and registers always","Nothing","Only PID"]'::jsonb, 0, 'Threads share memory and resources; have own stack/registers.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 6, 'IPC fastest for bulk same-machine data?', '["Shared memory","Pipe copy always faster","Signal only","File on NFS only"]'::jsonb, 0, 'Shared memory avoids kernel copy for large payloads.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 6, 'exec() after fork does?', '["Replace process image","Create second parent","Duplicate only memory forever","Close all network always mandatory"]'::jsonb, 0, 'exec loads new program into existing process.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 6, 'Orphan process adopted by?', '["init/systemd in Unix","Parent zombie","No one ever","Child of itself"]'::jsonb, 0, 'When parent dies, init re-parents orphan processes.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 6, 'User mode to kernel mode transition via?', '["System call trap","printf only","Local variable assign","Comment in code"]'::jsonb, 0, 'Traps/interrupts enter kernel to perform privileged work.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 6, 'Multiprogramming increases?', '["CPU utilization by overlapping execution","Single process speed always linear","Need for one program only","Eliminates memory need"]'::jsonb, 0, 'Multiple processes keep CPU busy while others wait on I/O.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 7, 'Paging avoids which fragmentation?', '["External","Internal only always eliminated too","None","Disk fragmentation only"]'::jsonb, 0, 'Fixed pages eliminate external holes; internal may remain.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 7, 'TLB purpose is?', '["Cache page table translations","Sort processes","Encrypt memory","Replace RAM"]'::jsonb, 0, 'TLB speeds virtual to physical address translation.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 7, 'Page fault occurs when?', '["Referenced page not in RAM","Cache hit","TLB always hit","Successful read from register"]'::jsonb, 0, 'OS must fetch page from disk into memory.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 7, 'Thrashing means?', '["Excessive paging low CPU utilization","CPU overheating","Fast execution","No swapping"]'::jsonb, 0, 'System spends time paging rather than executing processes.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 7, 'Working set model guides?', '["How many frames process needs resident","File naming","DNS cache","Scheduling quantum only"]'::jsonb, 0, 'Keep working set in memory to avoid thrashing.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 7, 'Copy-on-write after fork optimizes?', '["Delay copying pages until write","Immediate full copy always","Disable paging","Remove TLB"]'::jsonb, 0, 'Share read-only pages until modified.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 7, 'Segmentation uses?', '["Variable sized logical units","Fixed pages only","No addresses","Only cache lines"]'::jsonb, 0, 'Segments represent logical program parts like code/data.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 7, 'Effective access time formula includes?', '["Hit ratio and miss penalty","Only CPU GHz","Only disk size","Process name length"]'::jsonb, 0, 'EAT = hit * t_mem + (1-hit) * (t_mem + page_fault_penalty).', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 7, 'Inverted page table used to?', '["Save space in large physical memory systems","Increase external fragmentation","Replace TLB only","Sort files"]'::jsonb, 0, 'One entry per physical frame rather than per virtual page.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 7, 'Belady anomaly seen in?', '["FIFO page replacement","LRU stack algorithm","OPT theoretical","Never occurs"]'::jsonb, 0, 'FIFO may fault more when frames increase.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 8, 'Round Robin uses?', '["Time quantum and ready queue","Shortest job first always","No preemption","Random pick forever"]'::jsonb, 0, 'Each process gets fixed CPU slice cyclically.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 8, 'SJF minimizes?', '["Average waiting time if lengths known","Response time always","I/O wait only","Memory usage"]'::jsonb, 0, 'Shortest Job First optimizes average wait when job times known.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 8, 'Convoy effect in FCFS?', '["Short jobs wait behind long job","Deadlock","Starvation impossible","TLB flush"]'::jsonb, 0, 'Head-of-line blocking delays small processes.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 8, 'Priority scheduling risk?', '["Starvation of low priority","No preemption ever","Equal time slices always","Eliminates I/O"]'::jsonb, 0, 'Low priority may never run; aging mitigates.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 8, 'Multilevel feedback queue adapts?', '["Process behavior between queues","Only static assignment","Disk scheduling","File permissions"]'::jsonb, 0, 'Processes move between priority queues based on CPU/I/O behavior.', 'hard');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 8, 'Turnaround time equals?', '["Completion time minus arrival time","First response only","CPU burst only","Waiting plus quantum always only"]'::jsonb, 0, 'Total time in system from arrival to completion.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 8, 'Preemptive scheduling allows?', '["Interrupt running process for higher priority/quantum expiry","Never interrupt","Only on I/O completion of same process always running","Disable ready queue"]'::jsonb, 0, 'Running process may be forced to ready state.', 'easy');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 8, 'Response time differs from turnaround as?', '["Time to first response vs total completion","Same metric","Disk seek time","Page fault count"]'::jsonb, 0, 'Interactive systems care about first output latency.', 'medium');
INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (2, 8, 'Lottery scheduling provides?', '["Probabilistic proportional CPU share","Deterministic strict priority only","No fairness","Real-time guarantees always"]'::jsonb, 0, 'Tickets give proportional long-run CPU share.', 'hard');
