INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (3, 11, 'Which SQL clause filters rows before grouping?', '["WHERE","HAVING","ORDER BY","GROUP BY"]'::jsonb, 0, 'WHERE filters individual rows before aggregation occurs.', 'easy');
