INSERT INTO questions (subject_id, topic_id, question, options, correct_answer, explanation, difficulty) VALUES (3, 11, 'HAVING filters what?', '["Groups after aggregation","Rows before aggregation","Columns only","Indexes"]'::jsonb, 0, 'HAVING applies conditions to grouped results unlike WHERE.', 'easy');
